arguments.argument:
if(global.myself.team == TEAM_BLUE)
    image_index = 1;
else
    image_index = 0;

if(global.myself.object == -1 or global.myself.class != CLASS_ENGINEER)
{
    instance_destroy();
    exit; 
}

var offset;
offset = 145;
//Draw building HUDs, prioritizing in the order of Sentry, Dispenser.
if (global.myself.sentry)
{
    drawHealth(45, view_hview[0]-(offset-22), global.myself.sentry.hp, global.myself.sentry.maxHp);
    draw_sprite_ext(sprite_index, global.myself.team, view_xview[0]+5, view_yview[0]+view_hview[0]-offset, 2, 2, 0, c_white, 1);
	   offset += 70;
}

if (global.myself.dispenser)
{
    drawHealth(45, view_hview[0]-(offset-22), global.myself.dispenser.hp, global.myself.dispenser.maxHp);
    draw_sprite_ext(sprite_index, 2+global.myself.team, view_xview[0]+5, view_yview[0]+view_hview[0]-offset, 2, 2, 0, c_white, 1);
	   offset += 70;
}
